public class NumberUtils_isNumber_TriageGen2Test {



    @Test
    public void testIsNumber_Integer() {
        assertTrue(NumberUtils.isNumber("123"));
        assertTrue(NumberUtils.isNumber("0"));
        assertTrue(NumberUtils.isNumber("-123"));
        assertTrue(NumberUtils.isNumber("+123")); // Note: code logic handles '+' via allowSigns/foundDigit flow
        // Re-evaluating code: '+' is only allowed if allowSigns is true (after 'E'). 
        // However, '-' is handled at the start. Let's test based on implementation.
        assertFalse(NumberUtils.isNumber("+123")); 
    }














}

