package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {







    @Test
    public void testIsNumber_Decimal() {
        assertTrue(NumberUtils.isNumber("123.456"));
        assertTrue(NumberUtils.isNumber("123."));
        assertTrue(NumberUtils.isNumber(".123")); // Implementation: chars[0] is '.', start=0, i=0. loop runs.
        // Wait, if chars[0] is '.', start=0. i=0. chars[0]=='.'. hasDecPoint=true. i becomes 1.
        // If str is ".1", sz=2, start=0. i=0. loop i < 1. i=0 is '.', hasDecPoint=true. i=1.
        // Loop ends. i=1 < 2. chars[1] is '1'. returns true.
        assertTrue(NumberUtils.isNumber(".1"));
        assertFalse(NumberUtils.isNumber("1.2.3"));
        assertFalse(NumberUtils.isNumber("1e2.3"));
    }










}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {









    @Test
    public void testIsNumber_Exponent() {
        assertTrue(NumberUtils.isNumber("1e10"));
        assertTrue(NumberUtils.isNumber("1E10"));
        assertTrue(NumberUtils.isNumber("1e-10"));
        assertTrue(NumberUtils.isNumber("1e+10"));
        assertFalse(NumberUtils.isNumber("e10"));
        assertFalse(NumberUtils.isNumber("1e"));
        assertFalse(NumberUtils.isNumber("1e+-10"));
        assertFalse(NumberUtils.isNumber("1e1.5"));
        assertFalse(NumberUtils.isNumber("1E1E1"));
    }








}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        // l, L (not allowed with exponent or decimal)
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));
        assertFalse(NumberUtils.isNumber("123.4l"));
        assertFalse(NumberUtils.isNumber("1e2l"));

        // Invalid qualifiers
        assertFalse(NumberUtils.isNumber("123g"));
        assertFalse(NumberUtils.isNumber("123.d")); // d is not allowed after decimal in this impl
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {













    @Test
    public void testIsNumber_EdgeCases() {
        assertFalse(NumberUtils.isNumber("-"));
        assertFalse(NumberUtils.isNumber("."));
        assertFalse(NumberUtils.isNumber("1e-"));
        assertFalse(NumberUtils.isNumber("1e+"));
        assertFalse(NumberUtils.isNumber("1.e2")); // hasExp is true, hasDecPoint is true -> false

        // Test for the specific branch: i < sz + 1 && allowSigns && !foundDigit
        // This happens when string ends in 'E' or 'e' and we are looking for a sign
        // But the logic 'foundDigit' is reset to false when sign is encountered.
        assertFalse(NumberUtils.isNumber("1E-")); 
    }




}

